import java.util.*;

class Solution {
  public long maxBalancedSubsequenceSum(int[] nums) {
    long[] keys = new long[nums.length];
    for (int i = 0; i < nums.length; i++) keys[i] = (long) nums[i] - i;
    long[] sorted = keys.clone();
    Arrays.sort(sorted);
    int unique = 0;
    for (long key : sorted) if (unique == 0 || sorted[unique - 1] != key) sorted[unique++] = key;
    long[] bit = new long[unique + 1];
    Arrays.fill(bit, Long.MIN_VALUE);
    long answer = Long.MIN_VALUE;
    for (int i = 0; i < nums.length; i++) {
      int rank = Arrays.binarySearch(sorted, 0, unique, keys[i]) + 1;
      long best = Math.max(0, query(bit, rank));
      long current = best + nums[i];
      update(bit, rank, current);
      answer = Math.max(answer, current);
    }
    return answer;
  }

  private long query(long[] bit, int index) {
    long result = Long.MIN_VALUE;
    for (; index > 0; index -= index & -index) result = Math.max(result, bit[index]);
    return result;
  }

  private void update(long[] bit, int index, long value) {
    for (; index < bit.length; index += index & -index) bit[index] = Math.max(bit[index], value);
  }
}
